 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    sep = 8
    row_seps = [r for r in range(h) if all(v == sep for v in g[r])]
    col_seps = [c for c in range(w) if all(g[r][c] == sep for r in range(h))]
    r_edges = [-1] + row_seps + [h]
    c_edges = [-1] + col_seps + [w]
    panels = {}
    for ri in range(len(r_edges)-1):
        for ci in range(len(c_edges)-1):
            rs = range(r_edges[ri]+1, r_edges[ri+1])
            cs = range(c_edges[ci]+1, c_edges[ci+1])
            cells = {(r-rs.start, c-cs.start): g[r][c]
                     for r in rs for c in cs if g[r][c] != 0}
            panels[(ri, ci)] = (r_edges[ri]+1, c_edges[ci]+1,
                                r_edges[ri+1]-r_edges[ri]-1,
                                c_edges[ci+1]-c_edges[ci]-1, cells)
    colors = {v for p in panels.values() for v in p[4].values() if v != sep}
    for color in colors:
        # A known adjacent pair of panels establishes that this color's paired
        # shapes are horizontal reflections of one another.
        paired = False
        for (ri, ci), (r0, c0, ph, pw, cells) in panels.items():
            left = {(r, c): v for (r, c), v in cells.items() if v == color}
            other = panels.get((ri, ci+1))
            if not left or not other:
                continue
            or0, oc0, oh, ow, ocells = other
            right = {(r, c): v for (r, c), v in ocells.items() if v == color}
            if left and right and ph == oh and pw == ow and set(left) == {(r, pw-1-c) for r,c in right}:
                paired = True
                break
        if not paired:
            continue
        additions = []
        for (ri, ci), (r0, c0, ph, pw, cells) in panels.items():
            shape = {(r,c) for (r,c),v in cells.items() if v == color}
            if not shape:
                continue
            # Extend a singleton panel to an empty adjacent partner.
            for dci in (1, -1):
                other = panels.get((ri, ci+dci))
                if other is None:
                    continue
                or0, oc0, oh, ow, ocells = other
                if ocells or ph != oh or pw != ow:
                    continue
                additions.append((or0, oc0, {(r, pw-1-c) for r,c in shape}, color))
                break
        for r0, c0, shape, col in additions:
            for r, c in shape:
                g[r0+r][c0+c] = col
    return g
